SELECT i.seller_id,COUNT(*) joined_items,SUM(i.price) joined_sales,AVG(i.price) joined_price,AVG(r.review_score*1.0) review_mean,AVG(julianday(o.order_delivered_carrier_date)-julianday(o.order_purchase_timestamp)) purchase_pack,AVG(julianday(o.order_delivered_carrier_date)-julianday(o.order_approved_at)) approve_pack FROM order_items i LEFT JOIN order_reviews r ON r.order_id=i.order_id LEFT JOIN orders o ON o.order_id=i.order_id WHERE i.seller_id IN ('febab0275244b9a49a623f0bd613ca2f','fe2032dab1a61af8794248c8196565c9','fc906263ca5083d09dce42fe02247800','fa40cc5b934574b62717c68f3d678b6d','2a7dc43cecabf23403078e2188437d1d') GROUP BY i.seller_id
